/*!
 * @file      multirate_coeffs.h
 * @brief     Rate-change filter, low-rate IIR and test tone for E02.
 *
 *            fs = 48000 Hz, low rate 8000 Hz (factor 6). Prototype: 180-tap
 *            Kaiser-windowed low-pass, pass band to 3000 Hz, 60 dB target from
 *            4000 Hz. IIR: order 4 Butterworth, -3 dB at 2000 Hz at the low rate.
 *            Tone: 1000 Hz at 0.25 of full scale.
 *
 *            Generated by `uv run coursework/E02-multirate/design.py`;
 *            edit the design there, not this file.
 */

#ifndef __MULTIRATE_COEFFS_H__
#define __MULTIRATE_COEFFS_H__

#include "dsp/biquad.h"

/*
 * Low-pass prototype h[0] .. h[N-1] at the codec rate, unity gain
 * at DC; the decimator applies it as is, the interpolator scaled
 * by MULTIRATE_FACTOR.
 */
#define MULTIRATE_SAMPLE_RATE (48000u)
#define MULTIRATE_FACTOR (6u)
#define MULTIRATE_TAPS (180u)
extern const float MultirateTaps[MULTIRATE_TAPS];

/*
 * IIR low-pass at the low rate, second-order sections with
 * BIQUAD_COEFFS each in the order biquad.h expects.
 */
#define RATE8K_IIR_SECTIONS (2u)
extern const float Rate8kIirSos[RATE8K_IIR_SECTIONS * BIQUAD_COEFFS];

/*
 * One period of the test tone at the low rate.
 */
#define RATE8K_TONE_HZ (1000u)
#define RATE8K_TONE_LEN (8u)
extern const float Rate8kTone[RATE8K_TONE_LEN];

#endif /* __MULTIRATE_COEFFS_H__ */
